import 'package:flutter/material.dart';
import 'package:flutter_localizations/flutter_localizations.dart';
import 'models/task.dart';
import 'services/task_store.dart';
import 'services/notification_service.dart';

void main() async { WidgetsFlutterBinding.ensureInitialized(); await TaskStore.load(); await NotificationService.init(); runApp(const DailyScheduleApp()); }

class DailyScheduleApp extends StatelessWidget {
  const DailyScheduleApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'جدولي اليومي', locale: const Locale('ar'), supportedLocales: const [Locale('ar'), Locale('en')], localizationsDelegates: GlobalMaterialLocalizations.delegates, theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: const Color(0xFFFAFAF8), colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF356859), brightness: Brightness.light), fontFamily: 'sans'), home: const HomeScreen());
}

class HomeScreen extends StatefulWidget { const HomeScreen({super.key}); @override State<HomeScreen> createState() => _HomeScreenState(); }
